```c
#include <stdio.h>

int main(void) {
    int p;
    if (scanf("%d", &p) != 1) return 0;

    while (p--) {
        long long L, A, B;
        scanf("%lld %lld %lld", &L, &A, &B);

        long long n = B - A + 1;
        long long low = 0;
        long long high = n;

        while (high - low > 1) {
            long long t = low + (high - low) / 2;
            __int128 sum = (__int128)t * (2 * (__int128)A + t - 1) / 2;

            if (sum < L) {
                low = t;
            } else {
                high = t;
            }
        }

        printf("%lld\n", low + 1);
    }

    return 0;
}
```

